<?php
class CartController extends BaseController { public function index(mysqli $db): void { require_customer();$id=(int)$_SESSION['user_id'];$a=$_GET['action']??'';$pid=(int)($_GET['id']??0);if($a==='add'&&$pid){Cart::add($db,$id,$pid);header('Location: cart.php');exit;}if($a==='remove'&&$pid){Cart::remove($db,$id,$pid);header('Location: cart.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update'])){Cart::update($db,$id,$_POST['qty']??[]);header('Location: cart.php');exit;}$items=Cart::items($db,$id);$d=$this->data($db);$d['items']=$items;render('customer/cart',$d);} }
